51	export class LeaseTakenError extends Error {
52	  constructor(resource, holder, requested = undefined, available = undefined) {
53	    super(`lease for resource ${String(resource)} is already held`);
54	    this.name = 'LeaseTakenError';
55	    this.code = LeaseTakenError.code;
56	    this.resource = resource;
57	    this.holder = holder ?? null;
58	    this.requested = requested;
59	    this.available = available;
60	  }
61	}
62	LeaseTakenError.code = 'LEASE_TAKEN';
