109	// Binary min-heap ordered by (expiresAt, insertion order). Expiry heaps are
110	// used three ways: one global heap drives reclamation, each resource gets one
111	// for lazy capacity accounting, and each quota node gets one for lazy quota
112	// accounting. Renewals push fresh nodes and retire the old ones, so reclaiming
113	// expired leases only walks entries that are actually due instead of scanning
114	// the whole table.
115	class ExpiryQueue {
116	  constructor() {
117	    this.nodes = [];
118	  }
119	
120	  get size() {
121	    return this.nodes.length;
122	  }
123	
124	  push(node) {
125	    const nodes = this.nodes;
126	    nodes.push(node);
127	    let i = nodes.length - 1;
128	    while (i > 0) {
129	      const parent = (i - 1) >> 1;
130	      if (expiresBefore(nodes[i], nodes[parent])) {
131	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
132	        i = parent;
133	      } else {
134	        break;
135	      }
136	    }
137	  }
138	
139	  peek() {
140	    return this.nodes[0];
141	  }
142	
143	  pop() {
144	    const nodes = this.nodes;
145	    const top = nodes[0];
146	    const last = nodes.pop();
147	    if (nodes.length > 0) {
148	      nodes[0] = last;
149	      let i = 0;
150	      for (;;) {
151	        const left = i * 2 + 1;
152	        const right = left + 1;
153	        let next = i;
154	        if (left < nodes.length && expiresBefore(nodes[left], nodes[next])) {
155	          next = left;
156	        }
157	        if (right < nodes.length && expiresBefore(nodes[right], nodes[next])) {
158	          next = right;
159	        }
160	        if (next === i) {
161	          break;
162	        }
163	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
164	        i = next;
165	      }
166	    }
167	    return top;
168	  }
169	}
