178	// Binary min-heap of wait-request deadlines. Timeout cleanup pops due
179	// requests in deadline order instead of scanning every pending request, so
180	// a large waiting population costs O(expired * log n), never O(n) per call.
181	class DeadlineQueue {
182	  constructor() {
183	    this.nodes = [];
184	  }
185	
186	  get size() {
187	    return this.nodes.length;
188	  }
189	
190	  push(node) {
191	    const nodes = this.nodes;
192	    nodes.push(node);
193	    let i = nodes.length - 1;
194	    while (i > 0) {
195	      const parent = (i - 1) >> 1;
196	      if (deadlineBefore(nodes[i], nodes[parent])) {
197	        [nodes[i], nodes[parent]] = [nodes[parent], nodes[i]];
198	        i = parent;
199	      } else {
200	        break;
201	      }
202	    }
203	  }
204	
205	  peek() {
206	    return this.nodes[0];
207	  }
208	
209	  pop() {
210	    const nodes = this.nodes;
211	    const top = nodes[0];
212	    const last = nodes.pop();
213	    if (nodes.length > 0) {
214	      nodes[0] = last;
215	      let i = 0;
216	      for (;;) {
217	        const left = i * 2 + 1;
218	        const right = left + 1;
219	        let next = i;
220	        if (left < nodes.length && deadlineBefore(nodes[left], nodes[next])) {
221	          next = left;
222	        }
223	        if (right < nodes.length && deadlineBefore(nodes[right], nodes[next])) {
224	          next = right;
225	        }
226	        if (next === i) {
227	          break;
228	        }
229	        [nodes[i], nodes[next]] = [nodes[next], nodes[i]];
230	        i = next;
231	      }
232	    }
233	    return top;
234	  }
235	}
236	
237	function deadlineBefore(a, b) {
238	  if (a.deadline !== b.deadline) {
239	    return a.deadline < b.deadline;
240	  }
241	  return a.tie < b.tie;
242	}
