247	export function createRegistry({ ttlMs, clock = Date.now, logPath = null } = {}) {
248	  if (!Number.isFinite(ttlMs) || ttlMs <= 0) {
249	    throw new TypeError('ttlMs must be a positive finite number');
250	  }
251	  if (typeof clock !== 'function') {
252	    throw new TypeError('clock must be a function');
253	  }
254	
255	  const snapshotPath = logPath === null ? null : `${logPath}.snapshot`;
256	  const defaultTtlMs = ttlMs;
257	  // resource -> FIFO array of queue positions. A group request listing the
258	  // same resource in several rows occupies one position per row.
259	  const waitQueues = new Map();
260	  // requestId -> group, while the request is still queued.
261	  const pendingGroups = new Map();
262	  // token -> { resource, holder, expiresAt, ttlMs, legacy, heapSeq, chain,
263	  // epoch, counted }
264	  const leases = new Map();
265	  // Every token this instance knows about, including replayed credentials
266	  // that were already released or reclaimed, so a freshly minted token can
267	  // never reuse a dead credential's string.
268	  const knownTokens = new Set();
269	  // resource -> Set of tokens currently attached to it. A share resource
270	  // usually carries several live credentials; the set makes release and
271	  // reclaim O(1) regardless of how many shares coexist.
272	  const slots = new Map();
273	  // resource -> last committed credential epoch. The first grant of a
274	  // resource opens it at 1 and every later committed credential advances it
275	  // by exactly one, including retakes by the same holder and credentials
276	  // handed to woken requests. A release, reclaim, expiry or restart never
277	  // moves it backwards, so a resource with no live lease still reports the
278	  // epoch its last credential carried.
279	  const epochs = new Map();
280	  // resource -> last committed checkpoint { height, hash, version, epoch }.
281	  // The version starts at 1 on the first committed write and advances by
282	  // exactly one per write; a lease handover, release, reclaim or restart
283	  // never resets it, and a chain reorganization may lower the height
284	  // freely. Lives next to the lease tables but moves nothing in them.
285	  const checkpoints = new Map();
286	  // resource -> runtime bookkeeping. Created lazily; an undeclared resource
287	  // is a capacity-1 resource with no quota chain.
288	  const resourceStates = new Map();
289	  // quota id -> { id, parentId, limit, live, heap, resources }. `live` is the
290	  // current share occupation counted against the limit, maintained per share
291	  // grant and released lazily by the quota's own expiry heap.
292	  const quotas = new Map();
293	  // The global expiry heap drives sweep(); resource and quota heaps drive
294	  // lazy, sub-linear availability checks.
295	  const expiryQueue = new ExpiryQueue();
296	  // One node per queued wait request, ordered by wait deadline. Nodes outlive
297	  // their request only until the next lazy pop, flagged `dead`.
298	  const deadlineQueue = new DeadlineQueue();
299	
300	  const counters = {
301	    granted: 0,
302	    renewed: 0,
303	    released: 0,
304	    reclaimed: 0,
305	  };
306	
307	  // Per-instance identity makes tokens unique across registries living in the
308	  // same process; one instance can never present a token another owns.
309	  registrySequence += 1;
310	  const registryId = registrySequence;
311	  let tokenSequence = 0;
312	  let queueOrder = 0;
313	  let deadlineTie = 0;
314	  let requestSequence = 0;
315	  let batchSequence = 0;
316	  // Monotonic id stamped on every persisted event; a snapshot records the
317	  // last id it folded in, so a log still containing the folded prefix (the
318	  // log swap failed) replays those events as no-ops instead of twice.
319	  let eventSeq = 0;
320	
321	  function mintToken(now, seq = tokenSequence) {
322	    // Pure candidate: nothing is committed until the event is on disk, so a
323	    // failed append rolls all the way back. Pids and instance ids can coincide
324	    // after a restart, so skip any sequence that collides with a credential
325	    // reconstructed from the log. The caller threads the sequence through when
326	    // it mints several tokens for one atomic write.
327	    let token;
328	    do {
329	      seq += 1;
330	      token = `lease-${process.pid}-${registryId}-${seq}-${now.toString(36)}`;
331	    } while (knownTokens.has(token));
332	    return { token, seq };
333	  }
334	
335	  function newExpiryNode(token, expiresAt, heapSeq) {
336	    return { token, expiresAt, heapSeq, order: queueOrder++ };
337	  }
338	
339	  // One node in every heap a lease occupies. The nodes are independent: each
340	  // heap retires its own stale entries lazily. Every push also bumps the
341	  // owner's heap version, so a reconcile at an unchanged reading still
342	  // re-judges after a grant or renewal changed the heap contents.
343	  // Push one lease node to the global expiry heap and to every owner
344	  // whose heap drives lazy observation. A share already recorded as
345	  // retired at an owner (a replay structurally superseding an unswept
346	  // lease) only needs its global node - it must be reclaimable - and is
347	  // skipped on that owner's heap, since its occupation was never
348	  // reconstructed there. Every other push bumps the owner's heap
349	  // version, so a reconcile at an unchanged reading still re-judges
350	  // after a grant or renewal changed the heap contents.
351	  function pushLeaseHeaps(token, lease) {
352	    const node = newExpiryNode(token, lease.expiresAt, lease.heapSeq);
353	    expiryQueue.push(node);
354	    const rs = resourceStates.get(lease.resource);
355	    rs.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
356	    rs.version += 1;
357	    for (const quota of lease.chain) {
358	      quota.heap.push(newExpiryNode(token, lease.expiresAt, lease.heapSeq));
359	      quota.version += 1;
360	    }
361	  }
362	
363	  // Peek an owner heap for a lease that is live at `now` without
364	  // mutating anything: stale nodes are inspected but left in place for a
365	  // later reconcile to retire or for a dropStaleSlots displacement.
366	  function hasLiveHeapNode(owner, now) {
367	    for (const node of owner.heap.nodes) {
368	      const lease = leases.get(node.token);
369	      if (lease !== undefined && lease.heapSeq === node.heapSeq && node.expiresAt > now) {
370	        return true;
371	      }
372	    }
373	    return false;
374	  }
375	
376	  // Remove every node naming `token` from one expiry heap. Used when a
377	  // replay structurally supersedes an expired, unswept lease: the stale
378	  // share never occupied the reconstructed owner table, so its node leaves
379	  // the owner heap without any live-usage movement. Tokens are globally
380	  // unique, so matching the token alone (not the heap sequence) separates a
381	  // superseded lease from a fresh credential that happens to share seq 0.
382	  function removeHeapNodes(heap, token) {
383	    let i = 0;
384	    while (i < heap.nodes.length) {
385	      if (heap.nodes[i].token === token) {
386	        heap.nodes.splice(i, 1);
387	      } else {
388	        i += 1;
389	      }
390	    }
391	    // Restore the heap invariant in linear time after the removals.
392	    const nodes = heap.nodes;
393	    for (let j = (nodes.length >>> 1) - 1; j >= 0; j -= 1) {
394	      let parent = j;
395	      for (;;) {
396	        const left = parent * 2 + 1;
397	        const right = left + 1;
398	        let smallest = parent;
399	        if (left < nodes.length && expiresBefore(nodes[left], nodes[smallest])) {
400	          smallest = left;
401	        }
402	        if (right < nodes.length && expiresBefore(nodes[right], nodes[smallest])) {
403	          smallest = right;
404	        }
405	        if (smallest === parent) {
406	          break;
407	        }
408	        [nodes[parent], nodes[smallest]] = [nodes[smallest], nodes[parent]];
409	        parent = smallest;
410	      }
411	    }
412	  }
413	
414	  function isLive(lease, now) {
415	    return lease !== undefined && lease.expiresAt > now;
416	  }
417	
418	  function resourceStateFor(resource) {
419	    let rs = resourceStates.get(resource);
420	    if (rs === undefined) {
421	      rs = {
422	        capacity: 1,
423	        chain: [],
424	        declared: false,
425	        live: 0,
426	        heap: new ExpiryQueue(),
427	        // Shares observed expired (and so not counted at the current
428	        // reading) but still in the lease table awaiting a sweep. The map is
429	        // reversible: a reading that goes backwards revives entries that are
430	        // live again, exactly as a fresh isLive judgment would.
431	        retired: new Map(),
432	        watermark: -Infinity,
433	        checkedVersion: -1,
434	        // Heap layout version, bumped whenever a node is pushed (a grant or
435	        // a renewal moves a share's expiry): a reconcile at an unchanged
436	        // reading must still run again after a renewal so the new expiry is
437	        // judged at that reading.
438	        version: 0,
439	        // quota -> number of queued positions on this resource under it; the
440	        // set drives quota-indexed wake seeding.
441	        waitRefs: new Map(),
442	      };
443	      resourceStates.set(resource, rs);
444	    }
445	    return rs;
446	  }
447	
448	  function quotaChainFor(leafId) {
449	    const chain = [];
450	    let current = leafId;
451	    while (current !== null && current !== undefined) {
452	      const node = quotas.get(current);
453	      if (node === undefined) {
454	        throw new TypeError(`unknown quota ${String(current)}`);
455	      }
456	      chain.push(node);
457	      current = node.parentId;
458	    }
459	    chain.reverse();
460	    return chain;
461	  }
462	
463	  // Forget a lease from every owner's retired set without touching its
464	  // live usage: the share was already observed expired (a sweep projected
465	  // the retirement before its reclaim event landed).
466	  function purgeRetired(lease) {
467	    const rs = resourceStates.get(lease.resource);
468	    if (rs !== undefined) {
469	      rs.retired.delete(lease.token);
470	    }
471	    for (const quota of lease.chain) {
472	      quota.retired.delete(lease.token);
473	    }
474	  }
475	
476	  // Permanently remove a lease from the table (early release, reclaim, a
477	  // single-occupancy retake, or a replay superseding it). Owners that were
478	  // still counting the share lose it; owners that had already observed it
479	  // expired simply forget its retired entry.
480	  function retirePermanent(lease) {
481	    if (lease === undefined) {
482	      return;
483	    }
484	    const rs = resourceStates.get(lease.resource);
485	    if (rs !== undefined) {
486	      if (!rs.retired.has(lease.token)) {
487	        rs.live -= 1;
488	      }
489	      rs.retired.delete(lease.token);
490	    }
491	    for (const quota of lease.chain) {
492	      if (!quota.retired.has(lease.token)) {
493	        quota.live -= 1;
494	      }
495	      quota.retired.delete(lease.token);
496	    }
497	  }
498	
499	  // Reconcile one occupancy owner (a resource or one quota level) with the
500	  // passed clock reading. Occupancy is judged the way isLive judges it -
501	  // `expiresAt > now` - at every call, so a reading that goes backwards
502	  // revives shares an earlier reading had already retired. The owner's
503	  // watermark makes a monotonic sequence of readings pop lazily in expiry
504	  // order, and a backwards reading walk the retired set back onto the heap.
505	  function reconcile(owner, now) {
506	    const retired = [];
507	    if (now === owner.watermark && owner.version === owner.checkedVersion) {
508	      return retired;
509	    }
510	    if (now > owner.watermark) {
511	      while (owner.heap.size > 0) {
512	        const node = owner.heap.peek();
513	        if (node.expiresAt > now) {
514	          break;
515	        }
516	        owner.heap.pop();
517	        const lease = leases.get(node.token);
518	        if (lease === undefined) {
519	          // Released or reclaimed.
520	          continue;
521	        }
522	        if (lease.heapSeq !== node.heapSeq) {
523	          // Superseded by a renewal: discard the old node without retiring
524	          // anything (its heap entry is stale) and keep scanning.
525	          continue;
526	        }
527	        if (owner.retired.has(node.token)) {
528	          // Either a share that revived after a backwards reading and
529	          // expired again, or a share a replay retake structurally
530	          // superseded: its first retirement already moved this owner's
531	          // usage, so the heap node is simply dropped.
532	          continue;
533	        }
534	        owner.retired.set(node.token, {
535	          heapSeq: node.heapSeq,
536	          expiresAt: node.expiresAt,
537	        });
538	        owner.live -= 1;
539	        retired.push(node);
540	      }
541	    } else {
542	      // The reading moved backwards: every retired share that is live again
543	      // under the earlier reading returns, and its node goes back on the heap
544	      // so a later forward reading retires it in proper expiry order.
545	      for (const [token, record] of owner.retired) {
546	        const lease = leases.get(token);
547	        if (lease === undefined || lease.heapSeq !== record.heapSeq) {
548	          // Released/reclaimed meanwhile, or renewed after a revival: the
549	          // old record describes nothing current.
550	          owner.retired.delete(token);
551	          continue;
552	        }
553	        if (record.expiresAt > now) {
554	          owner.retired.delete(token);
555	          const node = {
556	            token,
557	            expiresAt: record.expiresAt,
558	            heapSeq: record.heapSeq,
559	            order: queueOrder++,
560	          };
561	          owner.heap.push(node);
562	          owner.live += 1;
563	          retired.push({ node, revived: true });
564	        }
565	      }
566	    }
567	    owner.watermark = now;
568	    owner.checkedVersion = owner.version;
569	    return retired;
570	  }
571	
572	  // Project a batch of global reclaim nodes through every owner they
573	  // occupy before wake planning in a sweep. Returns a record able to put
574	  // every owner exactly back if the log write fails.
575	  function projectReclaims(due, now) {
576	    const touched = [];
577	    const seen = new Set();
578	    const touch = (owner) => {
579	      if (owner !== undefined && !seen.has(owner)) {
580	        seen.add(owner);
581	        touched.push({ owner, watermark: owner.watermark, checkedVersion: owner.checkedVersion, retired: [] });
582	      }
583	    };
584	    for (const node of due) {
585	      const lease = leases.get(node.token);
586	      touch(resourceStates.get(lease.resource));
587	      for (const quota of lease.chain) {
588	        touch(quota);
589	      }
590	    }
591	    for (const entry of touched) {
592	      entry.retired = reconcile(entry.owner, now);
593	    }
594	    return touched;
595	  }
596	
597	  function revertProjections(touched) {
598	    for (const entry of touched) {
599	      const { owner } = entry;
600	      for (const item of entry.retired) {
601	        const node = item.node ?? item;
602	        owner.retired.delete(node.token);
603	        if (item.revived) {
604	          owner.live -= 1;
605	        } else {
606	          owner.live += 1;
607	        }
608	        owner.heap.push(node);
609	      }
610	      owner.watermark = entry.watermark;
611	    }
612	  }
613	
614	  function getSlots(resource) {
615	    let set = slots.get(resource);
616	    if (set === undefined) {
617	      set = new Set();
618	      slots.set(resource, set);
619	    }
620	    return set;
621	  }
622	
623	  function addSlot(resource, token) {
624	    getSlots(resource).add(token);
625	  }
626	
627	  function removeSlot(resource, token) {
