  const leaseEntries = [];
  for (const [token, lease] of leases.entries()) {
    leaseEntries.push({
      token,
      resource: lease.resource,
      holder: lease.holder,
      expiresAt: lease.expiresAt,
      ttlMs: lease.ttlMs,
      epoch: lease.epoch,
      batch: lease.batch ?? null,
      // Local tie-breaker for the sort below; stripped before writing.
      order: activeOrder.get(token) ?? 0,
    });
