      v: LOG_VERSION,
      type: 'checkpoint-all',
      at: now,
      items: entries.map((entry) => ({
        resource: entry.resource,
        height: entry.checkpoint.height,
        hash: entry.checkpoint.hash,
        version: entry.expectedVersion + 1,
        epoch: entry.epoch,
